const input = $json;
const candidates = [input.output, input.text, input.response, input.result, input.message?.content, input.data];
let raw = candidates.find(v => v !== undefined && v !== null && v !== '');
let parsed = {};
if (typeof raw === 'object') {
  parsed = raw;
  raw = JSON.stringify(raw);
} else if (typeof raw === 'string') {
  const fenced = raw.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const body = fenced ? fenced[1] : raw;
  const jsonMatch = body.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try { parsed = JSON.parse(jsonMatch[0]); } catch (error) { parsed = { parse_error: error.message }; }
  }
}
return [{ json: { ...input, raw_llm_output: raw ?? '', ...parsed } }];

